  ('Business Alliance Meeting', 'business-alliance-meeting-879f83', 'These zoom meetings through the Livermore Chamber of Commerce are 8-9:30 a.m., the first Wednesday of each month. Visit livermorechamber.org.', '2026-09-02T08:00:00-07:00', null, null, 'Livermore, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/a3c1b8d2-e817-4cd5-bb9e-9ecfc2114391.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/business-alliance-meeting/17855458/2026-09-02T08', 'approved', 'scraper', '879f83e26b57'),
  ('Low Impact Aerobics', 'low-impact-aerobics-3670d7', 'Classes are designed to be low-impact, energizing and fun-filled with the methods and movements involved to help strengthen and stabilize the body. Mondays, Wednesdays & Fridays 8:30–9:20 a.m. Drop-in fees $5(R)/$6(NR). Alcosta Senior & Community Center.', '2026-09-02T08:00:00-07:00', null, null, 'San Ramon, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/ed29e7c2-1ef4-44aa-9bf6-fa4143cee163.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/low-impact-aerobics/2094483529/2026-09-02T08', 'approved', 'scraper', '3670d71e9339'),
  ('Sole Mates Walking Group', 'sole-mates-walking-group-29235a', 'This free walking group at the Pleasanton Senior Center is 8:45-10 a.m., Wednesdays.', '2026-09-02T08:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/4d983d66-b391-4048-9879-54787a70f538.large.PNG', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/sole-mates-walking-group/19784771/2026-09-02T08', 'approved', 'scraper', '29235a93b92a'),
  ('Woodshop', 'woodshop-752a86', '9 a.m.-12 p.m., Monday, Wednesday, Friday. $5.75R/$6.75NR. Pleasanton Senior Center.', '2026-09-02T09:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/4996cc94-b530-4279-b179-f2fddf5f850c.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/woodshop/17034951/2026-09-02T09', 'approved', 'scraper', '752a86bc5588'),
  ('Care Coordination Services', 'care-coordination-services-5caf18', 'CityServe Care Coordination program connects individuals and families in need to local resources including basic needs, physical health, emotional wellness , employment & education and financial stability. Drop-in hours 9 a.m.-12 p.m. & 1-4 p.m., Mon.-Fri. Livermore Multi-Service Center, 3311 Pacific Ave.', '2026-09-02T09:00:00-07:00', null, null, 'Livermore, CA', 'other', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/553716e9-d685-4b8e-ac75-88e20ef13f28.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/care-coordination-services/19331712/2026-09-02T09', 'approved', 'scraper', '5caf18247f10'),
  ('The Lending Library', 'the-lending-library-81bcba', 'Borrow up to 6 books, enjoy reading in the lounge, or take home and return when finished. 9 a.m.-4 p.m., Mon.-Fri. Livermore Senior Center, 4444 East Ave.', '2026-09-02T09:00:00-07:00', null, null, 'Livermore, CA', 'education', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/e927e5aa-0545-487c-96da-885b0eac6708.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/the-lending-library/14924239/2026-09-02T09', 'approved', 'scraper', '81bcba57430c'),
  ('Sausalito to SF Ferry Trip', 'sausalito-to-sf-ferry-trip-d4d366', 'Go in motorcoach style with LARPD to enjoy a day in Sausalito for lunching, strolling and shopping in this quaint bayside town lined with seafood restaurants, local boutiques and art galleries. 9:30 a.m.-7 p.m., Sept. 24. $85R/$94 NR. Visit larpd.org.', '2026-09-02T09:00:00-07:00', null, null, 'Livermore, CA', 'arts', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/76a56556-542b-4ec4-bc83-c92ec367f3fd.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/sausalito-to-sf-ferry-trip/19784082/2026-09-02T09', 'approved', 'scraper', 'd4d3665a7bad'),
  ('Bocce Ball', 'bocce-ball-647e49', 'Join for Bocce Ball at the Alcosta Senior & Community Center. 9:30-11 a.m., Wednesdays. Drop-in fees apply.', '2026-09-02T09:00:00-07:00', null, null, 'San Ramon, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/ccfcba12-70b5-4c8e-997b-0788ed35b373.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/bocce-ball/17069279/2026-09-02T09', 'approved', 'scraper', '647e490ab5d4'),
  ('Strength Training & Toning', 'strength-training-toning-e035b8', 'Strength training with light weights for men and women in a fun environment to help boost energy and build muscle. Weights provided. Mondays, Wednesdays & Fridays 9:30-10:20 a.m. Drop-in fees apply. Alcosta Senior & Community Center.', '2026-09-02T09:00:00-07:00', null, null, 'San Ramon, CA', 'education', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/4996cc94-b530-4279-b179-f2fddf5f850c.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/strength-training-toning/12479454/2026-09-02T09', 'approved', 'scraper', 'e035b89746cb'),
  ('Baby Bounce', 'baby-bounce-d223f9', 'A first storytime experience to share with babies (ages 0-18 months who are not yet walking) and their caregivers. Each week we will share a short story with our babies, listen to music, and work on our bounces and rhymes! Toddlers that are walking and preschoolers are invited to join us at SMART on Monday mornings. Library staff may take photos, videos, or audio recordings at our events. Please tell us if you do not wish to be photographed, video-recorded, or audio-recorded. We will always respect your requests. An ASL (American Sign Language) interpreter or closed captioning can be provided for this program if requested at least seven business days in advance. For assistance, please contact your library or accessibility@aclibrary.org accessibility@aclibrary.org.', '2026-09-02T10:00:00-07:00', null, 'Dublin Library', 'Dublin, CA', 'family', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/ktNcfjmxDEOTnnRyxWvxSg.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/baby-bounce/19685391/2026-09-02T10', 'approved', 'scraper', 'd223f9008f36'),
  ('The Peddler Shop', 'the-peddler-shop-c9e841', 'Located inside the Pleasanton Senior Center, shop one of a kind gifts crafted by local seniors. 10 a.m.-2 p.m., Mon.-Fri.', '2026-09-02T10:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/3ebb7289-3fce-4766-aeb7-37291b61ad48.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/the-peddler-shop/19770378/2026-09-02T10', 'approved', 'scraper', 'c9e8412dd254'),
  ('Project Eden Youth Prevention Services Tabling', 'project-eden-youth-prevention-services-tabling-b02e93', 'Project Eden Youth Prevention Services provides general information, education, and supportive materials for youth, young adults, and parents on making healthy choices, creating a safe environment for discussing substance misuse, and exploring healthy alternatives. Feel free to stop by with any questions regarding our services, projects, or future parent workshops. Library staff may take photos, videos, or audio recordings at our events. Please tell us if you do not wish to be photographed, video-recorded, or audio-recorded. We will always respect your requests. An ASL (American Sign Language) interpreter or closed captioning can be provided for this program if requested at least seven (7) days in advance. For assistance, please contact your library or accessibility@aclibrary.org.', '2026-09-02T10:00:00-07:00', null, 'Dublin Library', 'Dublin, CA', 'family', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/yoL5Zzt2M0qET3y7JquWVg.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/project-eden-youth-prevention-services-tabling/19245919/2026-09-02T10', 'approved', 'scraper', 'b02e935bf121'),
  ('Yesterday Once More, Scenes from the Past', 'yesterday-once-more-scenes-from-the-past-98434b', 'This exhibit invites artists to step through the present and into the echoes of what once was through approximately 80 artworks of evocative imagery and bygone moments, this group exhibition explores the dialogue between nostalgia and personal history. Through Oct. 10. Visit firehousearts.org.', '2026-09-02T10:00:00-07:00', null, null, 'Pleasanton, CA', 'arts', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/710114be-cd90-41b9-ada1-8124eea6a694.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/yesterday-once-more-scenes-from-the-past/19658108/2026-09-02T10', 'approved', 'scraper', '98434b194c77'),
  ('Live Well, Be Well (50+)', 'live-well-be-well-50-c0b098', 'Join this discussion group focused on Healthy Aging where topics include body systems, disease prevention and vitality. 10-11:30 a.m., Wednesday. Robert Livermore Community Center. Free registration at larpd.org.', '2026-09-02T10:00:00-07:00', null, null, 'Livermore, CA', 'other', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/ed29e7c2-1ef4-44aa-9bf6-fa4143cee163.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/live-well-be-well-50-/19634848/2026-09-02T10', 'approved', 'scraper', 'c0b098144033'),
  ('Harrington Gallery Exhibition', 'harrington-gallery-exhibition-c68b50', 'The Firehouse Arts Center lobby exhibit features the work of Marina Omelianenko on the Nancy Thompson Memorial Wall with a collection of 15 serene watercolors. Through Sept. 5.', '2026-09-02T10:00:00-07:00', null, null, 'Pleasanton, CA', 'arts', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/578c97e7-f44c-457b-8dbe-cb5f51a2b569.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/harrington-gallery-exhibition/19427191/2026-09-02T10', 'approved', 'scraper', 'c68b50d80793'),
  ('American Mahjong', 'american-mahjong-b53454', 'Join for American Mahjong at the Alcosta Senior & Community Center. 10 a.m.-12 p.m., Wednesdays. Drop-in fees apply.', '2026-09-02T10:00:00-07:00', null, null, 'San Ramon, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/7b06ea32-047e-4854-a846-b1eea534918e.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/american-mahjong/15769741/2026-09-02T10', 'approved', 'scraper', 'b53454dfd4c5'),
  ('Swimming at East Bay Parks', 'swimming-at-east-bay-parks-770509', 'The 2026 swim season is here and Park District swim facilities will operate on a standardized season this May 16–Sept. 27, with all locations aligned to the same overall timeframe. For more information visit ebparks.org/recreation/swimming.', '2026-09-02T10:00:00-07:00', null, null, 'Pleasanton, CA', 'sports', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/4ce5c2aa-9694-47f3-b1df-eaef5c32cd30.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/swimming-at-east-bay-parks/18768160/2026-09-02T10', 'approved', 'scraper', '7705098e2b2f'),
  ('Eugene O''Neill National Historic Site', 'eugene-o-neill-national-historic-site-f65d14', 'The Eugene O''Neill National Historic Site is free to the public with reservations required, accessible via a complimentary National Park Service Shuttle which departs from The Museum of the San Ramon Valley. 10 a.m.-2 p.m., Wed.-Sun. Visit nps.gov/euon/index.htm.', '2026-09-02T10:00:00-07:00', null, null, 'Danville, CA', 'arts', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/dc02f4ea-22e8-4009-9bfa-dbf0c34ab4cb.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/eugene-o-neill-national-historic-site/17910440/2026-09-02T10', 'approved', 'scraper', 'f65d1407fbc0'),
  ('Volunteer with Niles Canyon Railway', 'volunteer-with-niles-canyon-railway-dd3b4b', 'Niles Canyon Railway is looking for volunteers for all levels of skill and experience. For more information visit ncry.org/volunteer/.', '2026-09-02T10:00:00-07:00', null, null, 'Sunol, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/5158b597-ded0-4f45-9b50-979221b639e6.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-with-niles-canyon-railway/15135294/2026-09-02T10', 'approved', 'scraper', 'dd3b4b6225ae'),
  ('Music & Movement at Civic Center Library', 'music-movement-at-civic-center-library-4a8c80', 'Enjoy songs and movement activities that build motor and social skills and increase independence as well as language development in a child. Perfect for ages 1-5. 10:15 a.m., Mon.. Wed., Fri. Livermore Civic Center Library.', '2026-09-02T10:00:00-07:00', null, null, 'Livermore, CA', 'education', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/32187304-bc9d-4d94-bb08-d6654de6c0d4.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/music-movement-at-civic-center-library/14404920/2026-09-02T10', 'approved', 'scraper', '4a8c80646691'),
  ('Care Giver Support Group', 'care-giver-support-group-c21493', 'These free presentations from City Serve of the Tri-Valley provide support for unpaid friends/family caregivers who care for a loved one. Connect with other caregivers and learn about available resources. 10:30-11:30 a.m., Thursdays through Dec. 17. Robert Livermore Community Center. Visit larpd.org.', '2026-09-02T10:00:00-07:00', null, null, 'Livermore, CA', 'family', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/2211d787-e928-497d-abe2-4335c2fbe08d.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/care-giver-support-group/19764154/2026-09-02T10', 'approved', 'scraper', 'c21493ffc4dc'),
  ('Drop-in Genealogy Assistance', 'drop-in-genealogy-assistance-31552a', 'Begin family history search with assistance by members of the Livermore-Amador Genealogical Society. 10:30 a.m.-12:30 p.m., Sept. 2. Livermore Civic Center Library, Room 135.', '2026-09-02T10:00:00-07:00', null, null, 'Livermore, CA', 'family', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/7a5a6c1c-e229-470c-93ab-6fdb4adf524b.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/drop-in-genealogy-assistance/19417422/2026-09-02T10', 'approved', 'scraper', '31552a3d714d'),
