  ('LPV Live Music featuring East Bay Grooveline', 'lpv-live-music-featuring-east-bay-grooveline-6c8f83', 'Come enjoy Live Music , food & wine offered with music beginning at 6pm.', '2026-09-04T20:30:00-07:00', null, 'Las Positas Vineyards', '1828 Wetmore Road, Livermore, CA 94550', 'music', array['tri-valley']::text[], '$5.0', false, false, 'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1200&q=70', 'https://www.lvwine.org/events/2026/9/ https:/www.laspositasvineyards.com/events-calendar', (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/9/September.html', 'approved', 'scraper', '6c8f839c5c9d'),
  ('Fire Pit Fridays featuring JNeen', 'fire-pit-fridays-featuring-jneen-04609a', 'Join us for live music featuring JNeen from 6–9 PM. Open seating, no reservations required. Enjoy our award-winning wines by the glass or bottle, along with delicious food from our kitchen designed to perfectly complement our wine selection. Please note: Friday nights are 18+. No outside food or alcohol is permitted. To continue bringing you great live music, a $5 live music fee per person will apply.', '2026-09-04T21:00:00-07:00', null, 'Del Valle Winery', '4948 Tesla Rd., Livermore, CA 94550', 'music', array['tri-valley']::text[], null, false, false, 'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1200&q=70', null, (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/9/September.html', 'approved', 'scraper', '04609af95617'),
  ('Karaoke at Longevity', 'karaoke-at-longevity-0caee8', 'Ready to get your singing on? Always wanted to be on stage with a spotlight? Join us and show the crowd what you got. This is a judgement free zone and made for fun. Bring your friends and enjoy a fun filled evening with laughter and good times. Oh, don''t forget good wine by the glass and bottle too. Doors open at 6:30pm', '2026-09-04T23:00:00-07:00', null, 'Longevity Wines', '2271 S. Vasco Rd, Livermore, CA 94550', 'music', array['tri-valley']::text[], 'Cost: $10 (pay at the door)', false, false, 'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1200&q=70', null, (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/9/September.html', 'approved', 'scraper', '0caee8aacaa6'),
  ('Estate Block Party at Concannon Vineyard', 'estate-block-party-at-concannon-vineyard-a25d5b', 'September 5–7 | 11:30 AM–5:00 PM Live Music Daily | 12:00–4:00 PM Celebrate Labor Day Weekend with three days of live music,...', '2026-09-05T01:30:00-07:00', null, null, '4590 Tesla Rd, Livermore, CA', 'music', array['tri-valley']::text[], null, false, false, 'https://patch.com/img/cdn20/users/25432498/20260828/032850/estate-block-party-600x600___28152849541.jpg', null, (select id from sources where slug = 'crawl-patch-pleasanton'), 'https://patch.com/california/pleasanton/calendar/event/20260905/a7acf9f7-ca23-40ab-8c52-455ab5799e19/estate-block-party-at-concannon-vineyard', 'approved', 'scraper', 'a25d5be2f7ef'),
  ('Estate Block Party | Featuring SugarBear', 'estate-block-party-featuring-sugarbear-b5405d', 'SugarBear kicks off the weekend with an energetic mix of soul, funk, and reggae guaranteed to get you moving. Grab a bottle of your favorite Concannon or Cuda Ridge wine, find a spot on the lawn, and settle in for an afternoon of great music, local food, and vineyard views. This free community event is open to all, and kids are welcome.', '2026-09-05T05:00:00-07:00', null, 'Cuda Ridge Wines', '4590 Tesla Road, Livermore, CA 94550', 'food-drink', array['tri-valley']::text[], null, false, false, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1200&q=70', 'https://cudaridgewines.com/event/estate-block-party-featuring-sugarbear/', (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/9/September.html', 'approved', 'scraper', 'b5405d36556d'),
