  ('Estate Block Party | Featuring LunaFish', 'estate-block-party-featuring-lunafish-fc4bc3', 'Celebrate Labor Day Weekend with three days of live music, local food, and award-winning wines from Concannon and Cuda Ridge Wines. Day 2 features LunaFish with an eclectic mix of psychedelic rock classics and crowd favorites. Pair the music with handcrafted pizza from Fratelli''s or authentic German fare from Essen then kick back with a glass of wine and enjoy Sunday afternoon.', '2026-09-06T05:00:00-07:00', null, 'Cuda Ridge Wines', '4590 Tesla Road, Livermore, CA 94550', 'music', array['tri-valley']::text[], null, false, false, 'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1200&q=70', 'https://cudaridgewines.com/event/estate-block-party-featuring-lunafish/', (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/9/September.html', 'approved', 'scraper', 'fc4bc33813b0'),
  ('Scottish Highland Gathering & Games', 'scottish-highland-gathering-games-c5a5b9', 'A Bay Area tradition since 1866, be thrilled by world-class competitions and celebrate Scotland’s rich culture with traditional music, delicious food and breathtaking performances. 8 a.m.-6 p.m., Sept. 5-6. Visit alamedacountyfair.com.', '2026-09-06T08:00:00-07:00', null, null, 'Pleasanton, CA', 'festival', array['pleasanton']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/873ff963-113a-451c-afe5-f6792235c6ae.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/scottish-highland-gathering-games/19583545/2026-09-06T08', 'approved', 'scraper', 'c5a5b97f395f'),
