  ('Toddler Storytime', 'toddler-storytime-035ed0', 'Rhymes, songs, bounces and books for the whole family. Build a foundation for lifelong reading and learning at Storytime. 11-11:30 a.m., Thursdays. Pleasanton Library.', '2026-09-10T11:00:00-07:00', null, null, 'Pleasanton, CA', 'family', array['pleasanton']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/1cb22258-a406-42da-966e-7089df4b428d.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/toddler-storytime/19643484/2026-09-10T11', 'approved', 'scraper', '035ed0e07084'),
  ('Storytime at San Ramon Library', 'storytime-at-san-ramon-library-beed5b', 'Attending Storytime is a wonderful opportunity for young children to develop language, early literacy and social skills. Participants are welcome to stay for a 15-minute play session at the end of storytime. 11:15-11:45 a.m., Thursdays.', '2026-09-10T11:00:00-07:00', null, null, 'San Ramon, CA', 'family', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/b2f9d310-0e0f-4560-91ca-1e6508bcdbcf.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/storytime-at-san-ramon-library/19455875/2026-09-10T11', 'approved', 'scraper', 'beed5b26381e'),
