  ('Homework Help at Rincon Branch', 'homework-help-at-rincon-branch-9d3878', 'The Livermore Rincon Branch Library homework help program offers free help to students in preschool through 12th grade. Adult volunteers assist students with homework or practice with reading and math. 3-5 p.m., Mon., Tues., Thurs. 2-4 p.m., Wed. Through May 13 excluding holidays.', '2026-09-10T15:00:00-07:00', null, null, 'Livermore, CA', 'education', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/0d26f6c3-9b4c-42fb-a60b-23d647434084.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/homework-help-at-rincon-branch/19636469/2026-09-10T15', 'approved', 'scraper', '9d3878b63ff6'),
  ('Livermore Thursday Farmers Market', 'livermore-thursday-farmers-market-416ba1', 'Featuring over 50 vendors, join to explore, taste and shop fresh produce. 4-8 p.m., Thursdays. Carnegie Park.', '2026-09-10T16:00:00-07:00', null, null, 'Livermore, CA', 'market', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/7a5fa526-ae1c-4de0-925d-879520be27e9.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/livermore-thursday-farmers-market/18509531/2026-09-10T16', 'approved', 'scraper', '416ba1c5b8a5'),
