  ('LPV Live Music featuring Luna Fish', 'lpv-live-music-featuring-luna-fish-275880', 'Come enjoy Live Music , food & wine offered with music beginning at 6pm.', '2026-09-11T20:30:00-07:00', null, 'Las Positas Vineyards', '1828 Wetmore Road, Livermore, CA 94550', 'music', array['tri-valley']::text[], '$5.0', false, false, 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=1200&q=70', 'https://www.lvwine.org/events/2026/9/ https:/www.laspositasvineyards.com/events-calendar', (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/9/September.html', 'approved', 'scraper', '2758800f127a'),
  ('Fire Pit Fridays featuring Road Runner', 'fire-pit-fridays-featuring-road-runner-ad7e3c', 'Join us for live music featuring Road Runner from 6-9 PM. Open seating no reservations required. Enjoy our award winning wines by the glass or bottle along with delicious food from our kitchen designed to perfectly complement our wine selection. Please note Friday nights are 18+. No outside food or alcohol. $5 live music fee per person.', '2026-09-11T21:00:00-07:00', null, 'Del Valle Winery', '4948 Tesla Rd., Livermore, CA 94550', 'music', array['tri-valley']::text[], null, false, false, 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=1200&q=70', null, (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/9/September.html', 'approved', 'scraper', 'ad7e3c757634'),
  ('McGrail Vineyards Friday Night Live ft. Bryan Loweree', 'mcgrail-vineyards-friday-night-live-ft-bryan-loweree-9079dd', 'Join us for a special Friday Night Live on our scenic Vineyard Patio for an evening of live music great wine and sunset views overlooking the beautiful Livermore Valley. Set beneath glowing caf lights with sweeping vineyard and valley views this concert style experience offers a more intimate listening room ambiance with seating provided. Relax and unwind as Bryan Loweree a Nashville based singer songwriter takes stage.', '2026-09-11T21:00:00-07:00', null, 'McGrail Vineyards and Winery', '5600 Greenville Road, Livermore, CA 94550', 'music', array['tri-valley']::text[], '$15', false, false, 'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1200&q=70', 'https://www.exploretock.com/mcgrailvineyardsandwinery/event/596642/friday-night-live-summer-concert-series-at-mcgrail', (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/9/September.html', 'approved', 'scraper', '9079ddbcb2e1'),
