  ('Volunteer with CityServe', 'volunteer-with-cityserve-327622', 'Immediate volunteer opportunities are available as a Caring Visitor, RideCare Driver or Souper Tuesday community meal contributor. Call (925) 222-2273 or e-mail or e-mail serve@cityservecares.org.', '2026-09-22T10:00:00-07:00', null, null, 'Livermore, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1200&q=70', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-with-cityserve/17909277/2026-09-22T10', 'approved', 'scraper', '327622d44152'),
  ('Volunteer with Hope Hospice', 'volunteer-with-hope-hospice-2a8523', 'Hope patient care volunteers help patients and their families in many different ways by interacting with patients, escorting a canine companion to visit patients, or helping in the office or special event. For more information visit hopehospice.com/volunteering.', '2026-09-22T10:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/34225951-25dc-4ddd-82fd-3d49963a0c2d.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-with-hope-hospice/13575908/2026-09-22T10', 'approved', 'scraper', '2a8523603f7a'),
  ('Sing & Learn Babies', 'sing-learn-babies-66d7fe', 'Babies from birth to 12 months will enjoy songs, action rhymes, and playtime and share a book together in each lively session. 10:15-10:45 a.m., Tuesday. Livermore Civic Center Library.', '2026-09-22T10:00:00-07:00', null, null, 'Livermore, CA', 'music', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/7fb5320e-4e71-48b0-b220-3c622838492c.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/sing-learn-babies/18162084/2026-09-22T10', 'approved', 'scraper', '66d7fee882a5'),
  ('Living Your Best Life', 'living-your-best-life-685fab', 'Learn about the 8 dimensions of wellness, nutrition and practical steps to achieve these goals, presented by City Serve of the Tri-Valley. 10:30-11:30 a.m., Sept. 22. Pleasanton Senior Center.', '2026-09-22T10:00:00-07:00', null, null, 'Pleasanton, CA', 'education', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/985bfe0c-f7ee-42ee-b093-1c99b66a0c57.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/living-your-best-life/19769840/2026-09-22T10', 'approved', 'scraper', '685fabe4faa6'),
  ('Taste of City Center', 'taste-of-city-center-39ff7b', 'By popular demand, City Center Bishop Ranch, San Ramon’s lively open-air dining, shopping and entertainment destination, is bringing back its signature restaurant week, Taste of City Center, Sept. 18-27, with casual eats, elevated dinners and exclusive deals across the destination''s acclaimed dining lineup. Savor the flavors of the season during Taste of City Center—our very own restaurant week celebrating every delicious bite our eateries have to offer. From quick bites to leisurely dinners, enjoy special prix fixe menus, limited-time dishes, and curated pairings from all your favorite spots. Spend $300 at participating restaurants between September 18-27 and receive a free ticket to September Sips!', '2026-09-22T11:00:00-07:00', null, 'City Center Bishop Ranch', 'San Ramon, CA', 'food-drink', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/S1czmw69kUO10r8FzWI7Yg.large.jpg', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/taste-of-city-center/19720200/2026-09-22T11', 'approved', 'scraper', '39ff7bbaf809'),
  ('Toddler Storytime', 'toddler-storytime-357ccc', 'Toddlers aged 2-5 and their families are invited to join us for stories, songs, and fingerplays in the Virginia Bennet Room every Tuesday from 11:00-11:30 am. No registration required, although space is limited to 30 children. An ASL (American Sign Language) interpreter or closed captioning can be provided for this program if requested at least seven (7) business days in advance. For assistance, please contact your library or accessibility@aclibrary.org accessibility@aclibrary.org.', '2026-09-22T11:00:00-07:00', null, 'Dublin Library', 'Dublin, CA', 'family', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/uiWjJCm_f0SX3yd10AQWBg.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/toddler-storytime/19685402/2026-09-22T11', 'approved', 'scraper', '357ccc1adcb6'),
  ('Souper Tuesday Free Lunch', 'souper-tuesday-free-lunch-275a2b', 'Souper Tuesday Free Lunch through City Serve. 11 a.m.-12 p.m., Tuesdays. CityServe of the Tri-Valley, 3311 Pacific Ave., Livermore.', '2026-09-22T11:00:00-07:00', null, null, 'Livermore, CA', 'other', array['tri-valley']::text[], null, true, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/20b44e62-34ca-4bb0-8ada-a3cb6842a97f.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/souper-tuesday-free-lunch/17777429/2026-09-22T11', 'approved', 'scraper', '275a2bcb2851'),
