  ('Afterschool Teen Zone', 'afterschool-teen-zone-e8fd5e', 'Join other teens after school at the Pleasanton Library for homework, games, and hanging out. The program is drop-in on school days from 3-4 p.m.', '2026-09-22T15:00:00-07:00', null, null, 'Pleasanton, CA', 'festival', array['pleasanton']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/f8c07f5c-600d-4b4d-b145-085ea8475199.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/afterschool-teen-zone/19768575/2026-09-22T15', 'approved', 'scraper', 'e8fd5e8656b0'),
  ('Homework Help at Rincon Branch', 'homework-help-at-rincon-branch-2d4cc0', 'The Livermore Rincon Branch Library homework help program offers free help to students in preschool through 12th grade. Adult volunteers assist students with homework or practice with reading and math. 3-5 p.m., Mon., Tues., Thurs. 2-4 p.m., Wed. Through May 13 excluding holidays.', '2026-09-22T15:00:00-07:00', null, null, 'Livermore, CA', 'education', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/0d26f6c3-9b4c-42fb-a60b-23d647434084.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/homework-help-at-rincon-branch/19636469/2026-09-22T15', 'approved', 'scraper', '2d4cc0e76f64'),
