  ('The Peddler Shop', 'the-peddler-shop-2fda7c', 'Located inside the Pleasanton Senior Center, shop one of a kind gifts crafted by local seniors. 10 a.m.-2 p.m., Mon.-Fri.', '2026-09-30T10:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/3ebb7289-3fce-4766-aeb7-37291b61ad48.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/the-peddler-shop/19770378/2026-09-30T10', 'approved', 'scraper', '2fda7cc5e225'),
  ('Yesterday Once More, Scenes from the Past', 'yesterday-once-more-scenes-from-the-past-0990e6', 'This exhibit invites artists to step through the present and into the echoes of what once was through approximately 80 artworks of evocative imagery and bygone moments, this group exhibition explores the dialogue between nostalgia and personal history. Through Oct. 10. Visit firehousearts.org.', '2026-09-30T10:00:00-07:00', null, null, 'Pleasanton, CA', 'arts', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/710114be-cd90-41b9-ada1-8124eea6a694.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/yesterday-once-more-scenes-from-the-past/19658108/2026-09-30T10', 'approved', 'scraper', '0990e630f0b8'),
  ('Live Well, Be Well (50+)', 'live-well-be-well-50-604f38', 'Join this discussion group focused on Healthy Aging where topics include body systems, disease prevention and vitality. 10-11:30 a.m., Wednesday. Robert Livermore Community Center. Free registration at larpd.org.', '2026-09-30T10:00:00-07:00', null, null, 'Livermore, CA', 'other', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/ed29e7c2-1ef4-44aa-9bf6-fa4143cee163.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/live-well-be-well-50-/19634848/2026-09-30T10', 'approved', 'scraper', '604f38f633a0'),
  ('American Mahjong', 'american-mahjong-b33828', 'Join for American Mahjong at the Alcosta Senior & Community Center. 10 a.m.-12 p.m., Wednesdays. Drop-in fees apply.', '2026-09-30T10:00:00-07:00', null, null, 'San Ramon, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/7b06ea32-047e-4854-a846-b1eea534918e.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/american-mahjong/15769741/2026-09-30T10', 'approved', 'scraper', 'b3382823481b'),
  ('Eugene O''Neill National Historic Site', 'eugene-o-neill-national-historic-site-aa3601', 'The Eugene O''Neill National Historic Site is free to the public with reservations required, accessible via a complimentary National Park Service Shuttle which departs from The Museum of the San Ramon Valley. 10 a.m.-2 p.m., Wed.-Sun. Visit nps.gov/euon/index.htm.', '2026-09-30T10:00:00-07:00', null, null, 'Danville, CA', 'arts', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/dc02f4ea-22e8-4009-9bfa-dbf0c34ab4cb.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/eugene-o-neill-national-historic-site/17910440/2026-09-30T10', 'approved', 'scraper', 'aa360182af0b'),
  ('Volunteer with Niles Canyon Railway', 'volunteer-with-niles-canyon-railway-434141', 'Niles Canyon Railway is looking for volunteers for all levels of skill and experience. For more information visit ncry.org/volunteer/.', '2026-09-30T10:00:00-07:00', null, null, 'Sunol, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/5158b597-ded0-4f45-9b50-979221b639e6.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-with-niles-canyon-railway/15135294/2026-09-30T10', 'approved', 'scraper', '4341410851c3'),
  ('Music & Movement at Civic Center Library', 'music-movement-at-civic-center-library-eb198c', 'Enjoy songs and movement activities that build motor and social skills and increase independence as well as language development in a child. Perfect for ages 1-5. 10:15 a.m., Mon.. Wed., Fri. Livermore Civic Center Library.', '2026-09-30T10:00:00-07:00', null, null, 'Livermore, CA', 'education', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/32187304-bc9d-4d94-bb08-d6654de6c0d4.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/music-movement-at-civic-center-library/14404920/2026-09-30T10', 'approved', 'scraper', 'eb198c1c2fa7'),
  ('Gentle Chair Aerobics', 'gentle-chair-aerobics-6eb076', 'A beginner program designed for anyone who is new to exercise or looking for gentle, seated chair exercises to develop balance and strength. Monday and Wednesdays, 10:30–11:15 a.m. Drop-in fees apply. Alcosta Senior & Community Center.', '2026-09-30T10:00:00-07:00', null, null, 'San Ramon, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/ed176397-4c7f-4c1d-a15d-ef504f800956.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/gentle-chair-aerobics/12479460/2026-09-30T10', 'approved', 'scraper', '6eb076875e6f'),
  ('Family Story Hour', 'family-story-hour-4ead62', 'Family Story Hour is a fun combination of books, finger plays, rhymes, songs, movement activities to help reinforce a lifelong love of learning while building language and literacy skills. 11:15-11:45 a.m., Wednesdays. Danville Library.', '2026-09-30T11:00:00-07:00', null, null, 'Danville, CA', 'family', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/1cb22258-a406-42da-966e-7089df4b428d.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/family-story-hour/19244706/2026-09-30T11', 'approved', 'scraper', '4ead622a76e0'),
  ('Senior Lunches (60+)', 'senior-lunches-60-8df284', 'Senior Lunches (60+) served in the Pleasanton Senior Center Main Hall M-F, 11:45 a.m.-12:45 p.m. Call Open Heart Kitchen at (925) 500-8241 for more information.', '2026-09-30T11:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/20b44e62-34ca-4bb0-8ada-a3cb6842a97f.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/senior-lunches-60-/19540691/2026-09-30T11', 'approved', 'scraper', '8df28464b2b9'),
  ('Pleasanton Art League Solo Exhibit', 'pleasanton-art-league-solo-exhibit-f26aa8', 'The Firehouse Arts Center features the work of Zina Kassab on the Nancy Thompson Memorial Wall. Through Oct. 24. Reception by the artist 1-3 p.m., Sept. 19. Visit firehousearts.org.', '2026-09-30T12:00:00-07:00', null, null, 'Pleasanton, CA', 'arts', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/710114be-cd90-41b9-ada1-8124eea6a694.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/pleasanton-art-league-solo-exhibit/19708297/2026-09-30T12', 'approved', 'scraper', 'f26aa8d68afd'),
  ('Bingo at Pleasanton Senior Center', 'bingo-at-pleasanton-senior-center-8dfab2', 'Join for Bingo at the Pleasanton Senior Center, 1-3 p.m., Wednesdays. Drop-in fees apply.', '2026-09-30T13:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/598eb1af-eb78-41c6-a5c5-7f3e681aca64.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/bingo-at-pleasanton-senior-center/19310654/2026-09-30T13', 'approved', 'scraper', '8dfab2a39ab4'),
