  ('Volunteer in the Parks', 'volunteer-in-the-parks-d94d60', 'Volunteers are vital to the East Bay Regional Parks with opportunities available year-round across the Park District. Visit ebparks.org/volunteer.', '2026-10-12T08:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/28a05bf0-fdf2-41ac-a1b6-f80a57be6b49.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-in-the-parks/16541555/2026-10-12T08', 'approved', 'scraper', 'd94d6056b1b7'),
  ('Fee Assistance Program', 'fee-assistance-program-f195b2', 'The City of Pleasanton Recreation Department provides a Fee Assistance Program for residents who would like to participate in recreation programs but may not have the financial means. For more information contact Recreation Services at (925) 931-5340.', '2026-10-12T09:00:00-07:00', null, null, 'Pleasanton, CA', 'other', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/4a5b8f40-1af8-42b9-bc93-571390474613.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/fee-assistance-program/18829415/2026-10-12T09', 'approved', 'scraper', 'f195b2f3aa92'),
  ('Drop-In Billiards', 'drop-in-billiards-01e84a', 'Join for Billiards at the Livermore Senior Center. 9 a.m.-4 p.m., Mon.-Tues; 9 a.m.-12:30 p.m., Wed.-Fri.; 1-4 p.m. Drop-in fees apply. 4444 East Ave.', '2026-10-12T09:00:00-07:00', null, null, 'Livermore, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1200&q=70', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/drop-in-billiards/14919529/2026-10-12T09', 'approved', 'scraper', '01e84a73510b'),
