  ('Tax-Aide Program Looking for New Volunteers', 'tax-aide-program-looking-for-new-volunteers-7845c2', 'AARP Tax-Aide is looking for volunteers to become members of a team providing free tax preparation service in Contra Costa County. The program provides comprehensive training and ongoing support. To learn more visit aarpfoundation.org/taxaidevolunteer.', '2026-10-12T10:00:00-07:00', null, null, 'Danville, CA', 'education', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/fd17d638-123c-4ae3-b32e-40fa25ecdc73.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/tax-aide-program-looking-for-new-volunteers/19569834/2026-10-12T10', 'approved', 'scraper', '7845c27cc3d1'),
  ('Volunteer with Spectrum Community Services', 'volunteer-with-spectrum-community-services-7aec93', 'Spectrum Community Services is looking for new volunteers to join the team in a variety of capacities.. For more information visit spectrumcs.org/volunteers.', '2026-10-12T10:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/47a03405-a091-4b38-885d-c4396536782c.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-with-spectrum-community-services/18751692/2026-10-12T10', 'approved', 'scraper', '7aec93c2316b'),
