  ('Volunteer with CityServe', 'volunteer-with-cityserve-c1a5f5', 'Immediate volunteer opportunities are available as a Caring Visitor, RideCare Driver or Souper Tuesday community meal contributor. Call (925) 222-2273 or e-mail or e-mail serve@cityservecares.org.', '2026-10-20T10:00:00-07:00', null, null, 'Livermore, CA', 'community', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/34225951-25dc-4ddd-82fd-3d49963a0c2d.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-with-cityserve/17909277/2026-10-20T10', 'approved', 'scraper', 'c1a5f51321fe'),
  ('Volunteer with Hope Hospice', 'volunteer-with-hope-hospice-de597f', 'Hope patient care volunteers help patients and their families in many different ways by interacting with patients, escorting a canine companion to visit patients, or helping in the office or special event. For more information visit hopehospice.com/volunteering.', '2026-10-20T10:00:00-07:00', null, null, 'Pleasanton, CA', 'community', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/34225951-25dc-4ddd-82fd-3d49963a0c2d.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-with-hope-hospice/13575908/2026-10-20T10', 'approved', 'scraper', 'de597f3fecbe'),
  ('Sing & Learn Babies', 'sing-learn-babies-077c20', 'Babies from birth to 12 months will enjoy songs, action rhymes, and playtime and share a book together in each lively session. 10:15-10:45 a.m., Tuesday. Livermore Civic Center Library.', '2026-10-20T10:00:00-07:00', null, null, 'Livermore, CA', 'music', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/7fb5320e-4e71-48b0-b220-3c622838492c.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/sing-learn-babies/18162084/2026-10-20T10', 'approved', 'scraper', '077c2044dc83'),
  ('Toddler Storytime', 'toddler-storytime-28e640', 'Toddlers aged 2-5 and their families are invited to join us for stories, songs, and fingerplays in the Virginia Bennet Room every Tuesday from 11:00-11:30 am. No registration required, although space is limited to 30 children. An ASL (American Sign Language) interpreter or closed captioning can be provided for this program if requested at least seven (7) business days in advance. For assistance, please contact your library or accessibility@aclibrary.org accessibility@aclibrary.org.', '2026-10-20T11:00:00-07:00', null, 'Dublin Library', 'Dublin, CA', 'family', array['tri-valley']::text[], null, false, true, 'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1200&q=70', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/toddler-storytime/19685402/2026-10-20T11', 'approved', 'scraper', '28e64057c930'),
  ('Souper Tuesday Free Lunch', 'souper-tuesday-free-lunch-661546', 'Souper Tuesday Free Lunch through City Serve. 11 a.m.-12 p.m., Tuesdays. CityServe of the Tri-Valley, 3311 Pacific Ave., Livermore.', '2026-10-20T11:00:00-07:00', null, null, 'Livermore, CA', 'other', array['tri-valley']::text[], null, true, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/20b44e62-34ca-4bb0-8ada-a3cb6842a97f.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/souper-tuesday-free-lunch/17777429/2026-10-20T11', 'approved', 'scraper', '6615461acc50'),
