  ('Volunteer at Tri-Valley Haven', 'volunteer-at-tri-valley-haven-3a7dbe', 'Tri-Valley Haven''s mission is to advocate for survivors of domestic violence, sexual assault and homelessness. Volunteers might field calls on the crisis line, take care of children, distribute food or work at the Thrift Store. Visit trivalleyhaven.org/volunteer/.', '2026-11-21T10:00:00-07:00', null, null, 'Livermore, CA', 'market', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/fbdc176a-1f56-47e6-bfc9-8aabb7ea86c9.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/volunteer-at-tri-valley-haven/13672438/2026-11-21T10', 'approved', 'scraper', '3a7dbe54d98d'),
  ('Chess Hour', 'chess-hour-466c29', 'Practice chess skills and meet other chess players for games at the library. All ages and experience levels are welcome with chess boards provided. 11 a.m.-12 p.m., Saturday. San Ramon Library.', '2026-11-21T11:00:00-07:00', null, null, 'San Ramon, CA', 'festival', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/a9c1569f-5607-4287-80f1-933176da3fdf.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/chess-hour/18686976/2026-11-21T11', 'approved', 'scraper', '466c291f9d21'),
  ('Holiday Craft Fair', 'holiday-craft-fair-ea23f8', 'Join us for our 1st Craft Fair', '2026-11-21T12:00:00-07:00', null, 'Danville Grange #85', '743 Diablo Road, Danville, CA, 94526', 'festival', array['tri-valley','all-day']::text[], null, false, true, 'https://img.evbuc.com/https%3A%2F%2Fcdn.evbuc.com%2Fimages%2F1174124236%2F2987941629003%2F1%2Foriginal.20260106-180947?crop=focalpoint&fit=crop&w=308&auto=format%2Ccompress&q=75&sharp=10&fp-x=0.5&fp-y=0.5&s=6d34d651b2c14eb9135c2c3b1bdd77a8', null, (select id from sources where slug = 'crawl-eventbrite-pleasanton'), 'https://www.eventbrite.com/e/holiday-craft-fair-tickets-1992952656043', 'approved', 'scraper', 'ea23f8ba8de7'),
  ('Chorus Eclectic – Tomorrow’s Yesterday', 'chorus-eclectic-tomorrow-s-yesterday-81b80a', 'Celebrate the enduring legacy of Indigenous First Nations through music with Chorus Eclectic’s Tomorrow’s Yesterday. This inspiring concert honors the values of stewardship, respect for nature, and caring for future generations through music that celebrates Native American artists. Blending powerful choral performances with a message of hope and connection, the program reflects on the gifts we’ve inherited and the responsibility we share to preserve them. Join Chorus Eclectic for an uplifting musical tribute to the past, present, and future.', '2026-11-21T16:00:00-07:00', null, 'Firehouse Arts Center', '4444 Railroad Ave., Pleasanton, CA, 94566', 'music', array['Presenting Series','pleasanton']::text[], '$31', false, false, 'https://www.firehousearts.org/wp-content/uploads/2026/07/Tomorrows-Yesterday-web-1920x1080-1.png', null, (select id from sources where slug = 'crawl-firehouse-arts-center'), 'https://www.firehousearts.org/calendar-event/chorus-eclectic-tomorrows-yesterday/', 'approved', 'scraper', '81b80a9b0d23')
