  ('Forejour – Tribute to Foreigner and Journey', 'forejour-tribute-to-foreigner-and-journey-5217d0', 'FOREJOUR pays tribute to the music of ‘80s mega bands FOREIGNER & JOURNEY, recreating the soundtrack of a generation with stunning accuracy', '2026-12-12T19:30:00-07:00', null, 'Almost Famous Wine Company', '2271 S. Vasco, Suite D, Livermore, CA 94550', 'music', array['tri-valley']::text[], '$40', false, false, 'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=1200&q=70', 'https://www.eventbrite.com/e/forejour-tribute-to-foreigner-and-journey-tickets-1992454481991?aff=lvwa&keep_tld=true', (select id from sources where slug = 'crawl-livermore-valley-wine-country'), 'https://www.lvwine.org/events/2026/12/December.html', 'approved', 'scraper', '5217d0bb76a4'),
  ('Andy Grammer: Greater Than Pt. II: A One Man Show', 'andy-grammer-greater-than-pt-ii-a-one-man-show-dd74d1', 'An intimate, high-energy evening with multi-platinum artist Andy Grammer. Stripped to its core, this one-man show blends acoustic performance, spoken word, storytelling, and real-time audience connection into something deeply personal and undeniably uplifting. With only a piano, a guitar, and a room full of voices, Andy turns the stage into a shared experience: moving effortlessly between chart- topping hits, new songs, and the stories behind them. Raw, funny, and fully present, it’s an invitation into the heart of the music.', '2026-12-12T20:00:00-07:00', null, 'Dougherty Valley Performing Arts Center', 'San Ramon, CA', 'music', array['tri-valley']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/d5306cc6-c56a-4bc8-bb32-438c079958df.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/andy-grammer-greater-than-pt-ii-a-one-man-show/19678025/2026-12-12T20', 'approved', 'scraper', 'dd74d1ca1e8f'),
