  ('Phil of Genesis – A Musical Tribute to Phil Collins & Genesis', 'phil-of-genesis-a-musical-tribute-to-phil-collins-genesis-60bc3b', 'Phil of Genesis brings the unforgettable music of Phil Collins and Genesis to life in this high-energy tribute show. Featuring seasoned musicians who faithfully recreate the sound and energy of the original recordings, the band delivers hit after hit from two legendary acts. From soaring ballads to chart-topping anthems, every performance honors the timeless songs that defined a generation. It’s a nostalgic concert that will have audiences singing along all night long. Learn more at philofgenesis.com .', '2026-12-19T19:30:00-07:00', null, 'Firehouse Arts Center', '4444 Railroad Ave., Pleasanton, CA, 94566', 'music', array['Presenting Series','pleasanton']::text[], '$29 – $38', false, false, 'https://www.firehousearts.org/wp-content/uploads/2026/07/Phil-of-Genesis-web-1920x1080-1.png', null, (select id from sources where slug = 'crawl-firehouse-arts-center'), 'https://www.firehousearts.org/calendar-event/phil-of-genesis/', 'approved', 'scraper', '60bc3b0d1051'),
  ('Livermore Farmers'' Market', 'livermore-farmers-market-3bbd85', 'The Livermore Farmers'' Market is Sunday, year-round. 9 a.m.-1 p.m., 206 South J St.', '2026-12-20T09:00:00-07:00', null, null, 'Livermore, CA', 'market', array['tri-valley']::text[], null, false, true, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/c044a9d0-a3c2-417b-94d5-c25e57f22287.large.png', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/livermore-farmers-market/17775650/2026-12-20T09', 'approved', 'scraper', '3bbd85cdb5a0'),
