  ('Anand Varma: Exploring Nature''s Hidden Worlds', 'anand-varma-exploring-nature-s-hidden-worlds-1ddda8', null, '2027-01-21T19:30:00-07:00', null, 'Bankhead Theater', '2400 First St, Livermore, CA 94550', 'arts', array['tri-valley']::text[], null, false, false, 'https://livermorearts.org/wp-content/uploads/2026/03/RDSS-Anand-Varma-600x600-1.png', null, (select id from sources where slug = 'crawl-bankhead-theater'), 'https://livermorearts.org/events/rdss-anand-varma/', 'approved', 'scraper', '1ddda85e3a31'),
  ('Music lessons with Pleasanton''s 1776-era fife and drum children''s band', 'music-lessons-with-pleasanton-s-1776-era-fife-and-drum-children-s-band-8c8657', 'Do you want your child (8-16) to experience the fun, education and social camaraderie of being in the marching band---but without the enormous time commitment of a school marching band? Look no further! We have been providing music and leadership education to Pleasanton-area kids since our first lesson on March 19th 2010. The Young American Patriots Fife & Drum Corps "YAPs" is a NON-POLITICAL children''s parade band dedicated to perpetuating the music, history & heritage of our nation''s founding through musical education & traditional value-based teaching. We teach fife (like a flute) and drum in a small group setting.', '2027-01-22T17:00:00-07:00', null, 'near Mohr Elementary school, call for details', 'Pleasanton, CA', 'music', array['pleasanton']::text[], null, false, false, 'https://citysparkstorage.blob.core.windows.net/portalimages/portalimages/uwBQlHvUUECCzxi7pqcQSg.large.jpg', null, (select id from sources where slug = 'crawl-pleasanton-weekly'), 'https://www.pleasantonweekly.com/calendar/#!/details/music-lessons-with-pleasanton-s-1776-era-fife-and-drum-children-s-band/19689145/2027-01-22T17', 'approved', 'scraper', '8c86578b2481'),
